import { Icon } from '@/components/Icons'

/**
 * `image` names a file in public/service-ui, all of which are 720×540 WebP
 * generated by scripts/optimize-images.mjs. Intrinsic size is declared once
 * below rather than per card, so the browser can reserve the box before the
 * bytes land — these sit inside an absolutely-positioned hero, but the mobile
 * grid is in normal flow and did shift without it.
 */
const CARD_IMAGE_WIDTH = 720
const CARD_IMAGE_HEIGHT = 540

type ServiceCard = {
  name: string
  status: string
  image: string
  alt: string
  to: string
  position: string
  depth: number
  scrollDirection: number
  imagePosition?: string
}

