function Card({ card, compact = false }: { card: ServiceCard; compact?: boolean }) {
  return (
    <a
      href={card.to}
      aria-label={`Explore ${card.name}`}
      data-pointer-layer
      className={`press group block overflow-hidden border border-white/80 bg-white shadow-[0_3px_8px_rgb(5_17_39/0.07),0_28px_60px_-26px_rgb(5_17_39/0.38)] ${
        compact ? 'rounded-lg' : 'rounded-xl'
      }`}
    >
      <span
        className={`border-b border-hairline px-3 py-2.5 sm:px-4 ${
          compact
            ? 'flex flex-col gap-1'
            : 'flex items-center justify-between gap-3'
        }`}
      >
        <span
          className={`${compact ? 'line-clamp-2' : 'truncate'} text-[11px] font-semibold leading-[1.25] text-ink sm:text-xs`}
        >
          {card.name}
        </span>
        <span className="flex shrink-0 items-center gap-1.5 text-[9px] font-medium text-ink-muted sm:text-[10px]">
          <span className="size-1.5 rounded-full bg-emerald-500 shadow-[0_0_0_3px_rgb(16_185_129/0.1)]" />
          {card.status}
          <Icon
            name="arrowUpRight"
            className="ml-0.5 size-3 text-blue-600 transition-transform duration-300 ease-out-expo group-hover:translate-x-0.5 group-hover:-translate-y-0.5"
          />
        </span>
      </span>

      <span className={`block overflow-hidden bg-surface ${compact ? 'aspect-[1.45]' : 'aspect-[1.5]'}`}>
        {/* Both variants point at the same file, so rendering the desktop and
            mobile sets together costs one fetch per card, not two. */}
        <img
          src={card.image}
          alt={card.alt}
          width={CARD_IMAGE_WIDTH}
          height={CARD_IMAGE_HEIGHT}
          loading={compact ? 'lazy' : 'eager'}
          decoding="async"
          className={`h-full w-full object-cover transition-transform duration-700 ease-out-expo group-hover:scale-105 ${
            card.imagePosition ?? 'object-center'
          }`}
        />
      </span>
    </a>
  )
}

export function HeroServiceCardsDesktop() {
  return (
    <aside
      aria-label="A look inside our service workspaces"
      className="pointer-events-none absolute inset-0 z-0 hidden xl:block"
    >
      {serviceCards.map((card, index) => (
        <div
          key={card.name}
          data-hero-service-card
          data-depth={card.depth}
          data-scroll-direction={card.scrollDirection}
          data-card-index={index}
          className={`pointer-events-auto absolute will-change-transform ${card.position}`}
        >
          <div data-hero-card-enter className="will-change-transform">
            <Card card={card} />
          </div>
        </div>
      ))}
    </aside>
  )
}

/**
 * Below xl this was a 2-up grid, which stacked six cards into three rows and
 * pushed the hero's actual content — headline, CTAs — off a phone screen. As a
 * carousel it occupies one row at any width and the cards get to be big enough
 * to read, which they were not at half a phone's width.
 *
 * CSS scroll-snap, no carousel library and no JS of our own. The cards are
 * links, so they are reachable by tab and focusing one scrolls it into view,
 * which is the keyboard story most JS carousels get wrong. It also degrades to
 * a plain scrollable row if anything fails.
 *
 * The negative margin and matching width let it bleed to the screen edges
 * through the hero's px-6, so a partial next card is visible — the cue that
 * says "this scrolls" without needing arrows or dots. `scroll-px-6` makes a
 * snapped card land flush with the headline above it rather than against the
 * viewport edge.
 */
export function HeroServiceCardsMobile() {
  return (
    <ul
      aria-label="A look inside our service workspaces"
      className="mt-[clamp(1.75rem,5vh,3rem)] -mx-6 flex w-[calc(100%+3rem)] snap-x snap-mandatory gap-3 overflow-x-auto overscroll-x-contain scroll-px-6 px-6 pb-2 [-ms-overflow-style:none] [scrollbar-width:none] xl:hidden [&::-webkit-scrollbar]:hidden"
    >
      {serviceCards.map((card, index) => (
        <li
          key={card.name}
          data-hero-service-card
          data-depth={card.depth}
          data-scroll-direction={card.scrollDirection}
          data-card-index={index}
          className="w-[68%] shrink-0 snap-start will-change-transform sm:w-[42%] md:w-[31%]"
        >
          <div data-hero-card-enter className="will-change-transform">
            <Card card={card} compact />
          </div>
        </li>
      ))}
    </ul>
  )
}
